"""Refresh the current whole-sector visual inspection page."""
from pathlib import Path
import json
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / "artifacts/north-city-01"

def main():
    sector=json.loads((OUT/"secteur08-checks.json").read_text(encoding="utf-8"))
    layout=json.loads((ROOT/"assets/source-art/north-city-01/sector08/scene.json").read_text(encoding="utf-8"))
    previous=json.loads((OUT/"checks.json").read_text(encoding="utf-8"))
    city=json.loads((ROOT/"assets/maps/north-city-01/city-plan09.json").read_text(encoding="utf-8"))
    city_svg=(OUT/"city-plan09.svg").read_text(encoding="utf-8")
    payload=json.dumps(dict(sector=sector,layout=layout,previous=previous,city=city),ensure_ascii=False).replace("</","<\\/")
    stamp=str((OUT/"secteur08-checks.json").stat().st_mtime_ns)
    production_stamp=str((OUT/"production10-checks.json").stat().st_mtime_ns)
    html=r'''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>09 · Quartier nord — grande ville</title>
<style>
:root{color-scheme:dark;font-family:Segoe UI,system-ui,sans-serif;background:#111820;color:#d9e2eb}*{box-sizing:border-box}body{margin:0}header{padding:18px 24px 12px;background:#17222d;border-bottom:1px solid #35414e}h1{font-size:24px;color:#e1c593;margin:5px 0 10px}h2{font-size:18px;color:#e1c593;margin:14px 0 8px}p{line-height:1.6;margin:8px 0;max-width:1050px}.tag,.muted{color:#a8b6c4}.tag{font-size:12px;letter-spacing:.08em}main{padding:16px 24px 32px;max-width:1600px;margin:auto}nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}button,a{font:inherit}button{border:1px solid #455767;border-radius:4px;color:#e1e8ed;background:#1e2b38;padding:8px 11px;cursor:pointer}button:hover,button[aria-pressed=true]{border-color:#d5b97d;background:#354553}a{color:#e1c593}.figure{position:relative;overflow:auto;max-height:80vh;background:#090e14;border:1px solid #35414e}.figure img{display:block;width:100%;max-width:none;height:auto;image-rendering:pixelated}.figure.native img{width:var(--native-width);max-width:none}.figure svg{position:absolute;inset:0;width:100%;height:100%;display:none;pointer-events:none}.figure svg rect{fill:transparent;stroke:#f7cc70;stroke-width:2}.figure svg text{font:600 17px Segoe UI;fill:#ffe6a4;paint-order:stroke;stroke:#111820;stroke-width:4px}.toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:10px 0}.columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px,360px);gap:24px;margin-top:16px}.box{background:#17212b;border:1px solid #35414e;border-radius:5px;padding:12px 16px;margin:12px 0}.note{border-left:3px solid #bc9e64;padding-left:12px}.parts{display:flex;gap:6px;flex-wrap:wrap}.parts button{font-size:13px}#selection{white-space:pre-wrap;font-size:13px;color:#dfc79d}.variants{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.variants img{width:100%;height:auto}.plan{width:100%;height:auto;max-width:896px}details{margin:14px 0}summary{cursor:pointer;color:#dec69d}@media(max-width:800px){header,main{padding-left:14px;padding-right:14px}.columns{grid-template-columns:1fr}h1{font-size:22px}}
.citymap{overflow:auto;max-height:82vh;border:1px solid #35414e;background:#404943}.citymap svg{display:block;width:100%;height:auto}.citymap.zoom svg{width:1344px;max-width:none}.districts{display:grid;grid-template-columns:repeat(auto-fit,minmax(235px,1fr));gap:12px}.legend09{display:flex;gap:12px;flex-wrap:wrap;font-size:13px}.legend09 i{display:inline-block;width:12px;height:12px;margin-right:5px}.cityselection{white-space:pre-wrap;color:#dfc79d}
</style>
<header><div class="tag">PROJECT RL · CITY-NORTH01-PLAN09 · TRACÉ PRÉ-VALIDÉ</div><h1>Quartier nord — une nouvelle grande ville</h1><p>Un plan original de <b>112 × 112 cases</b>, avec quartiers résidentiels, commerces, services publics, espaces verts et accès militaire. La première ville fixe la qualité visuelle, l’échelle et la perspective.</p></header>
<main><nav><button id="plan09Tab" aria-pressed="true">09 · Plan complet de la ville</button><button id="production10Tab" aria-pressed="false">10 · Dessin de B01</button><button id="quality08Tab" aria-pressed="false">08 · Témoin de finition</button></nav>
<section id="cityPlan"><p><b>100 bâtiments</b> · <b>22 intérieurs envisagés</b> · école, commissariat, pompiers, parc et quartiers d’habitation. Le terrain représenterait <b>7168 × 7168 px à taille native</b>.</p><div class="citymap" id="citymap">__CITY_SVG__</div><div class="toolbar"><button id="planZoom" aria-pressed="false">Agrandir le plan</button><a href="city-plan09.png" target="_blank">Ouvrir le plan complet</a></div><div class="legend09"><span><i style="background:#8c8172"></i>Maisons</span><span><i style="background:#747e83"></i>Immeubles</span><span><i style="background:#aa9365"></i>Commerces</span><span><i style="background:#6b8050"></i>Verdure</span><span><i style="background:#af7465"></i>Pompiers</span><span><i style="background:#728bb0"></i>Commissariat</span></div><p class="note"><b>Tracé pré-validé.</b> Les rues, les emprises et les accès sont conservés pour la suite. Les volumes et couleurs désignent les emprises et fonctions. Les bâtiments recevront leurs dessins propres au niveau de finition de la première ville.</p><div class="box"><h2>Choisir un bâtiment</h2><p>Cliquer une emprise pour retrouver son identifiant et préciser une retouche.</p><select id="cityPick" aria-label="Bâtiment à inspecter"><option value="">Choisir un bâtiment…</option></select><p id="citySelection" class="cityselection">B01 à B10 conservent les repères des lieux principaux ; les nouvelles parcelles ont leurs propres identifiants H.</p></div><h2>Des quartiers avec des fonctions distinctes</h2><div id="districts" class="districts"></div><div class="box"><h2>Raccords et commissariat</h2><p>Arrivée depuis le nord de la première map en <b>X 18 ; Y 1</b> et <b>X 18 ; Y 2</b>. La sortie mène vers la <b>caserne militaire</b>, au nord-est. Plusieurs itinéraires traversent les quartiers.</p><p>Le commissariat conserve un étage et deux sous-sols. Chacun des deux niveaux inférieurs a trois variantes d’agencement avec les mêmes textures ; leur choix reste fixé à la création de la partie et sauvegardé.</p></div><p class="muted">Le témoin 08 sert à juger la finition et l’échelle. L’aménagement de la grande ville est celui du plan 09. La proposition de plan reste séparée des cartes jouables existantes pendant cette revue.</p><details><summary>Références d’aménagement</summary><p>Plan original inspiré de la hiérarchie des rues, des îlots, des cours et des espaces verts de grandes villes européennes, avec les <a href="https://www.visitstrasbourg.fr/wp-content/uploads/2020/09/OTSR_Plan-guide_2021.pdf" target="_blank">plans de Strasbourg</a> et le <a href="https://www.paris.fr/pages/plans-donnees-et-documents-d-urbanisme-3708" target="_blank">parcellaire de Paris</a> comme références. Aucun tracé de ces villes n’est recopié.</p></details></section>
<section id="productionPanel" style="display:none"><h2>10-1 r04 · B01 — référence futuriste grimdark pré-validée</h2><p>Bâtiment pré-validé avec relais réseau, refroidissement, câbles endommagés, terminal d’accès, caméra et volets de sécurité. Le bâtiment reste sur son emprise de <b>9 × 6 cases</b>. Le personnage reste à 64 px ; la porte est conservée près de la gauche de la façade, selon l’approche <b>X 13 ; Y 97</b> du plan.</p><div class="figure" id="productionFigure"><img id="productionImage" src="production10-B01-native.png?__PROD_STAMP__" width="1024" height="768" alt="B01 r04 fermé pré-validé à son échelle native, avec le personnage, un corps et la rue R02 du plan pré-validé"></div><div class="toolbar"><button id="native10" aria-pressed="false">Afficher B01 à taille native</button><a href="production10-B01-native.png?__PROD_STAMP__" target="_blank">Ouvrir l’image complète</a></div><p class="note"><b>B01 r04 : dessin pré-validé le 5 novembre 2026.</b> Accord du joueur : « oui c’est bien comme ca :) ». Cette version sert de référence futuriste grimdark pour la suite. La validation définitive en jeu reste à faire. La reprise générale des décors reste à faire ; les égouts sont conservés en l’état.</p><details><summary>Avant / après · image r01 signalée et B01 r04 pré-validé</summary><div class="figure"><img src="production10-B01-avant-apres.png?__PROD_STAMP__" width="2048" height="800" style="width:2048px;max-width:none" alt="B01 r01 à gauche et proposition futuriste r04 à droite, vues natives avec le même personnage et la même implantation"></div></details><details><summary>Comparer à la première ville · même acteur natif</summary><div class="figure"><img src="production10-B01-comparaison.png?__PROD_STAMP__" width="1536" height="800" style="width:1536px;max-width:none" alt="Garage de référence à gauche et B01 à droite, bâtiments entiers, même ligne de sol et même personnage de 64 px"></div></details><details><summary>Repère de l’emprise au sol</summary><div class="figure"><img src="production10-B01-emprise.png?__PROD_STAMP__" width="1024" height="768" alt="Emprise au sol conservée de B01, X12 à20 et Y91 à96"></div></details><p><a href="../../docs/reviews/north-city-01/PRODUCTION10-B01-ACCEPTANCE-r04.json" target="_blank">Accord sur B01 r04 et source figée</a></p><p>Cette revue présente le bâtiment fermé. Son intérieur et sa validation en déplacement restent à réaliser.</p><p><a href="../../docs/reviews/north-city-01/CYBERPUNK11.md" target="_blank">Direction futuriste grimdark et périmètre de la reprise</a></p><p><a href="../../docs/reviews/north-city-01/PRODUCTION10-B01.md" target="_blank">Fiche de B01, sources et prompts</a></p></section>
<section id="qualityPanel" style="display:none"><p class="note">Témoin local pour examiner le niveau de détail, les matières et le personnage natif de 64 px. Le plan 09 présente l’aménagement propre à la grande ville.</p><nav id="views"><button data-view="ensemble" aria-pressed="true">08 · Vue d’ensemble</button><button data-view="comparaison" aria-pressed="false">Comparer à la première ville</button><button data-view="interieur" aria-pressed="false">Voir le personnage dans le logement</button></nav>
<div class="figure" id="figure"><img id="scene" src="secteur08-ensemble.png?__STAMP__" width="1152" height="800" alt="Secteur 08 avec quatre bâtiments, une rue en décroché, une cour et le personnage natif"><svg id="repere" viewBox="0 0 1152 800" aria-hidden="true"></svg></div>
<div class="toolbar"><button id="native" aria-pressed="false">Afficher à taille native</button><label><input type="checkbox" id="showParts"> Repères de retouche</label><a id="imageLink" href="secteur08-ensemble.png?__STAMP__" target="_blank">Ouvrir l’image complète</a></div><p class="muted">La vue est adaptée à la page. Le bouton « taille native » affiche les pixels exacts, sans agrandissement.</p>
<div class="columns"><section><h2>La reprise porte sur toute la scène</h2><p>Les bâtiments ont des silhouettes et des usages distincts : habitation endommagée, logement en coupe, épicerie et atelier. Les petits accès, bordures, conduites, vitrines, débris et objets de rue composent un même décor. Les toitures restent relevées au-dessus de façades courtes et les sols suivent les murs.</p><p>Les trottoirs sont continus, avec les joints conservés sur leurs bordures. Dans le logement, le parquet, la cuisine et le coin d’eau se distinguent ; le mobilier a été repris selon l’intérieur de la première ville. Corps, sang et dommages restent localisés.</p><p class="note"><b>Nouvelle proposition visuelle à pré-valider.</b> Cette composition précède la reprise des emprises et des collisions du secteur dans le plan jouable. Le prototype 07 a été refusé pour sa qualité visuelle ; il ne sert plus de référence graphique.</p>
<details><summary>Plans du quartier et variantes conservés</summary><p>Le plan de <b>112 × 112 cases</b>, les accès nord en <b>X 18 ; Y 1</b> et <b>X 18 ; Y 2</b>, les bâtiments et les deux sous-sols à trois variantes restent dans les données existantes. Leurs fichiers n’ont pas été réécrits pour cet aperçu.</p><img class="plan" src="plan.png" width="896" height="896" alt="Plan jouable antérieur conservé, distinct de la proposition visuelle 08"><div id="variants" class="variants"></div></details>
</section><aside><div class="box"><h2>Retouches par élément</h2><p>Chaque bâtiment et groupe de décors a un repère stable. Choisir un repère ci-dessous pour préciser une retouche.</p><div id="parts" class="parts"></div><p id="selection">Choisir un élément.</p></div><div class="box"><h2>État de la proposition</h2><p>Pré-validation graphique : en attente.<br>Validation définitive en jeu : en attente.</p><p class="muted">La campagne et les sauvegardes restent inchangées.</p><p><a href="../../docs/reviews/north-city-01/SECTEUR08.md" target="_blank">Fiche de revue et sources</a></p></div></aside></div>
</section></main><script id="data" type="application/json">__PAYLOAD__</script><script>
const {sector,layout,previous,city}=JSON.parse(document.getElementById('data').textContent);
const views={ensemble:{file:'secteur08-ensemble.png',width:1152,height:800,alt:'Secteur 08 avec quatre bâtiments, une rue en décroché, une cour et le personnage natif'},comparaison:{file:'secteur08-comparaison.png',width:1536,height:736,alt:'Première ville à gauche et nouveau secteur à droite, même personnage de 64 px dans les deux vues'},interieur:{file:'secteur08-interieur.png',width:1152,height:800,alt:'Même scène avec le personnage dans le logement ouvert, près du lit et de la cuisine'}};
let selected='ensemble';const scene=document.getElementById('scene'),figure=document.getElementById('figure'),overlay=document.getElementById('repere');
function mode(name){selected=name;const v=views[name];scene.src=v.file+'?__STAMP__';scene.width=v.width;scene.height=v.height;scene.alt=v.alt;figure.style.setProperty('--native-width',v.width+'px');document.getElementById('imageLink').href=scene.src;document.querySelectorAll('#views button').forEach(b=>b.setAttribute('aria-pressed',b.dataset.view===name));reperes()}
function reperes(){overlay.style.width=scene.clientWidth+'px';overlay.style.height=scene.clientHeight+'px';overlay.style.display=selected==='ensemble'&&!figure.classList.contains('native')&&document.getElementById('showParts').checked?'block':'none'}
scene.onload=reperes;window.addEventListener('resize',reperes);document.querySelectorAll('#views button').forEach(b=>b.onclick=()=>mode(b.dataset.view));document.getElementById('native').onclick=()=>{const on=figure.classList.toggle('native');document.getElementById('native').setAttribute('aria-pressed',on);document.getElementById('native').textContent=on?'Adapter à la page':'Afficher à taille native';reperes()};document.getElementById('showParts').onchange=reperes;
for(const p of layout.elements){const [x,y,w,h]=p.source_rect.map(v=>v*sector.source_uniform_scale);const r=document.createElementNS('http://www.w3.org/2000/svg','rect');r.setAttribute('x',x);r.setAttribute('y',y+32);r.setAttribute('width',w);r.setAttribute('height',h);const t=document.createElementNS('http://www.w3.org/2000/svg','text');t.setAttribute('x',x+5);t.setAttribute('y',y+52);t.textContent=p.id;overlay.append(r,t);const b=document.createElement('button');b.textContent=p.id;b.title=p.name;b.onclick=()=>{document.getElementById('selection').textContent=p.id+' · '+p.name;document.getElementById('showParts').checked=true;mode('ensemble')};document.getElementById('parts').append(b)}
for(const v of previous.variant_previews||[]){const d=document.createElement('div');const p=document.createElement('p');p.textContent='Sous-sol −'+v.floor+' · variante '+v.variant;const i=document.createElement('img');i.src=v.image;i.alt=p.textContent;d.append(p,i);document.getElementById('variants').append(d)}mode('ensemble');

function showPrimary(name){for(const [panel,button,id] of [['cityPlan','plan09Tab','plan'],['productionPanel','production10Tab','production'],['qualityPanel','quality08Tab','quality']]){document.getElementById(panel).style.display=name===id?'block':'none';document.getElementById(button).setAttribute('aria-pressed',name===id)}}
if(location.hash==='#b01')showPrimary('production');document.getElementById('plan09Tab').onclick=()=>showPrimary('plan');document.getElementById('production10Tab').onclick=()=>showPrimary('production');document.getElementById('quality08Tab').onclick=()=>showPrimary('quality');document.getElementById('planZoom').onclick=()=>{const on=document.getElementById('citymap').classList.toggle('zoom');document.getElementById('planZoom').textContent=on?'Voir tout le plan':'Agrandir le plan';document.getElementById('planZoom').setAttribute('aria-pressed',on)};
document.getElementById('native10').onclick=()=>{const f=document.getElementById('productionFigure');f.style.setProperty('--native-width','1024px');const on=f.classList.toggle('native');document.getElementById('native10').textContent=on?'Adapter B01 à la page':'Afficher B01 à taille native';document.getElementById('native10').setAttribute('aria-pressed',on)};
for(const q of city.districts){const d=document.createElement('div');d.className='box';const h=document.createElement('h2');h.textContent=q.id+' · '+q.name;const p=document.createElement('p');p.textContent=q.character;d.append(h,p);document.getElementById('districts').append(d)}
const pick=document.getElementById('cityPick');for(const b of city.buildings){const o=document.createElement('option');o.value=b.id;o.textContent=b.id+' · '+b.name;pick.append(o)}
function selectCity(id){const b=city.buildings.find(b=>b.id===id);if(!b)return;document.querySelectorAll('[data-building]').forEach(g=>g.classList.toggle('selected',g.getAttribute('data-building')===id));pick.value=id;const lines=[b.id+' · '+b.name,b.accessible?'Intérieur envisagé':'Décor extérieur / bâtiment fermé','Entrée proposée : X '+b.door[0]+' ; Y '+b.door[1],'Emprise : '+b.rects.map(r=>r.join(', ')).join(' / ')];if(id==='B08')lines.push('Étage et deux sous-sols à trois variantes chacun, choix à la création de partie.');document.getElementById('citySelection').textContent=lines.join('\n')}
pick.onchange=()=>selectCity(pick.value);document.getElementById('citymap').addEventListener('click',e=>{const g=e.target.closest('[data-building]');if(g)selectCity(g.getAttribute('data-building'))});document.getElementById('citymap').addEventListener('keydown',e=>{const g=e.target.closest('[data-building]');if(g&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectCity(g.getAttribute('data-building'))}});

</script></html>'''
    (OUT/"apercu.html").write_text(html.replace("__PAYLOAD__",payload).replace("__STAMP__",stamp).replace("__CITY_SVG__",city_svg).replace("__PROD_STAMP__",production_stamp),encoding="utf-8")
    print(OUT/"apercu.html")

if __name__=="__main__":
    main()

